{# Presentation only. Capture original fragments once in Q15; never parse them
   into replacement prose or modify their text/attributes/paragraph boundaries. #}
{%- macro classify(row, result) -%}
  {# Conservative height bounds, not a complete HTML parser or text validator.
     Unknown tags/attributes fall back to the original table, never lose data. #}
  {%- set result.long = row.purpose.count('<p>') >= 12 and row.purpose.count('<p>') <= 160 and row.purpose|striptags|length <= 30000 -%}
  {%- for fragment in row.purpose.split('<')[1:] -%}
    {%- set tag = fragment.split('>')[0] -%}
      {%- if tag not in ['p', '/p', 'strong', '/strong', 'em', '/em', 'code', '/code', 'ul', '/ul', 'li', '/li', '/a', '/div', 'div class="answer-detail" data-fact-id="resource-justification" data-status="complete"', 'p class="data-gap" data-requirement-id="SE-6b" data-fact-id="resource-allocation" data-status="missing"'] and not tag.startswith('a href="') -%}
      {%- set result.long = false -%}
    {%- endif -%}
  {%- endfor -%}
  {%- for paragraph in row.purpose.split('<p>')[1:] -%}
    {%- if paragraph.split('</p>')[0]|striptags|length > 400 -%}{%- set result.long = false -%}{%- endif -%}
  {%- endfor -%}
  {%- if row.purpose.count('<ul>') > 1 or row.purpose.count('<li>') > 8 -%}{%- set result.long = false -%}{%- endif -%}
  {%- for value, limit in [(row.title, 80), (row.budget, 80), (row.funding, 100)] -%}
    {# Collapse source indentation for the height estimate only, never output.
       Missing values retain the original facts, wording and attributes. #}
    {%- set visible = (value|striptags).split()|join(' ') -%}
    {%- if not visible or visible|length > limit or value|length > 2000 or value.count('<p') > 3 -%}{%- set result.long = false -%}{%- endif -%}
    {%- for fragment in value.split('<')[1:] -%}
      {%- set tag = fragment.split('>')[0] -%}
      {%- if tag not in ['p', '/p', 'strong', '/strong', 'div class="answer-detail"', '/div',
        'p data-fact-id="resource-amount-value" data-status="complete"',
        'p data-fact-id="resource-currency" data-status="complete"',
        'p class="data-gap" data-requirement-id="SE-6b" data-fact-id="resource-amount" data-status="missing"',
        'p data-fact-id="cost-coverage" data-status="complete"',
        'p class="data-gap" data-fact-id="grant-number" data-status="missing"',
        'p class="data-gap" data-requirement-id="SE-6b" data-fact-id="cost-coverage" data-status="missing"'] -%}{%- set result.long = false -%}{%- endif -%}
    {%- endfor -%}
  {%- endfor -%}
{%- endmacro -%}

{%- macro short_table(original, rows, word=false) -%}
  {# An output-specific hint, not a new answer renderer. Unknown or large fragments
     retain the original table. Never trim/rewrite the captured output. #}
  {%- set selection = namespace(short=1 <= rows|length <= 3, gap=false) -%}
  {%- for row in rows -%}
    {%- set selection.gap = selection.gap or 'data-fact-id="resource-amount" data-status="missing"' in row.budget -%}
    {%- for value, limit, paragraphs in [(row.title, 80, 1), (row.purpose, 200, 2), (row.budget, 80, 3), (row.funding, 100, 3)] -%}
      {%- set visible = (value|striptags).split()|join(' ') -%}
      {%- if not visible or visible|length > limit or value|length > 2000 or value.count('<p') > paragraphs -%}
        {%- set selection.short = false -%}
      {%- endif -%}
      {%- for fragment in value.split('<')[1:] -%}
        {%- set tag = fragment.split('>')[0] -%}
        {%- if tag not in ['p', '/p', 'strong', '/strong', 'em', '/em', 'code', '/code', '/div',
          'div class="answer-detail"',
          'div class="answer-detail" data-fact-id="resource-justification" data-status="complete"',
          'p class="data-gap" data-requirement-id="SE-6b" data-fact-id="resource-justification" data-status="missing"',
          'p class="data-gap" data-requirement-id="SE-6b" data-fact-id="resource-allocation" data-status="missing"',
          'p data-fact-id="resource-amount-value" data-status="complete"',
          'p data-fact-id="resource-currency" data-status="complete"',
          'p class="data-gap" data-requirement-id="SE-6b" data-fact-id="resource-amount" data-status="missing"',
          'p data-fact-id="cost-coverage" data-status="complete"',
          'p class="data-gap" data-fact-id="grant-number" data-status="missing"',
          'p class="data-gap" data-requirement-id="SE-6b" data-fact-id="cost-coverage" data-status="missing"'] -%}
          {%- set selection.short = false -%}
        {%- endif -%}
      {%- endfor -%}
    {%- endfor -%}
  {%- endfor -%}
  {%- if selection.short and selection.gap -%}
    {%- if word -%}
      {{- original|replace('<table class="resource-table">', '<table class="resource-table word-short-budget">'|safe, 1) -}}
    {%- else -%}
      {{- original|replace('<table class="resource-table">', '<table class="resource-table pdf-short-budget">'|safe, 1) -}}
    {%- endif -%}
  {%- else -%}{{ original }}{%- endif -%}
{%- endmacro -%}

{%- macro ordinary(header, rows) -%}
{%- if rows|length > 32 -%}
  {%- for group in rows|batch(32) -%}{{ ordinary(header, group) }}{%- endfor -%}
{%- else -%}
{%- set original -%}<table class="resource-table"><colgroup><col class="resource-purpose"><col class="resource-budget"><col class="resource-funding"></colgroup><thead>{{ header }}</thead><tbody>{% for row in rows %}{{ row.original }}{% endfor %}</tbody></table>{%- endset -%}
{%- import 'src/pdf/short-resource-rows.html.j2' as shortRows -%}
{{- shortRows.table(original, rows) -}}
{%- endif -%}
{%- endmacro -%}

{%- macro render(original, header, rows) -%}
  {%- set selection = namespace(any=false, eligible=[]) -%}
  {%- for row in rows -%}
    {%- set result = namespace(long=false) -%}
    {{ classify(row, result) }}
    {%- do selection.eligible.append(result.long) -%}
    {%- set selection.any = selection.any or result.long -%}
  {%- endfor -%}
  {%- if not selection.any -%}
    {%- import 'src/pdf/short-resource-rows.html.j2' as shortRows -%}
    {{- short_table(shortRows.table(original, rows), rows) -}}
  {%- else -%}
    {%- set pending = [] -%}
    {%- for row in rows -%}
      {%- if selection.eligible[loop.index0] -%}
        {%- if pending -%}{{ ordinary(header, pending) }}{%- do pending.clear() -%}{%- endif -%}
        <table class="resource-table pdf-resource-reading" data-item-id="{{ row.id }}"><colgroup><col class="resource-purpose"><col class="resource-budget"><col class="resource-funding"></colgroup><thead>{{ header }}<tr><td>{{ row.title }}</td><td>{{ row.budget }}</td><td>{{ row.funding }}</td></tr></thead><tbody style="break-inside: avoid"><tr><td colspan="3">{{ row.purpose }}</td></tr></tbody></table>
      {%- else -%}{%- do pending.append(row) -%}{%- endif -%}
    {%- endfor -%}
    {%- if pending -%}{{ ordinary(header, pending) }}{%- endif -%}
  {%- endif -%}
{%- endmacro -%}

{%- set contributorsPath = [uuids.adminDetailsCUuid, uuids.contributorsQUuid]|join(".") -%}
{%- set contributorsItems = repliesMap[contributorsPath]|reply_items -%}
{% if contributorsItems or dc.project.created_by or output_profile|default('review') != 'submission' %}<div id="dmp-contributors">
  {# __tr_block_0000:start #}<h2>參與人員與職責</h2>{# __tr_block_0000:end #}

  {% set contributors = [] %}
  {%- for contributor in contributorsItems -%}
    {%- set pathPrefix = [contributorsPath, contributor]|reply_path ~ "." -%}
    {%- set contributorName = repliesMap[pathPrefix ~ uuids.contributorNameQUuid]|reply_str_value -%}
    {%- set contributorEmail = repliesMap[pathPrefix ~ uuids.contributorEmailQUuid]|reply_str_value -%}
    {%- set contributorOrcid = repliesMap[pathPrefix ~ uuids.contributorOrcidQUuid] -%}
    {%- set contributorRoles = repliesMap[pathPrefix ~ uuids.contributorRoleQUuid]|reply_items -%}
    {%- set contributorAffiliationReply = repliesMap[pathPrefix ~ uuids.contributorAffiliationQUuid] -%}
    {%- if contributorName or contributorEmail or contributorOrcid or contributorRoles or contributorAffiliationReply -%}
      {%- set roles = [] -%}
      {%- for role in contributorRoles -%}
        {%- if role in dc.e.choices.keys() -%}
          {%- do roles.append(dc.e.choices[role].label) -%}
        {%- endif -%}
      {%- endfor -%}
      {%- do contributors.append({
        'name': contributorName,
        'email': contributorEmail,
        'orcid': contributorOrcid,
        'roles': roles|sort,
        'affiliation': contributorAffiliationReply,
      }) -%}
    {%- endif -%}
  {%- endfor -%}

  {%- if contributors|length > 0 -%}
  <ul>
  {% for contributor in contributors %}
    {# __tr_block_0001:start #}<li class="contributor">
      <span class="name"><strong>{# __tr_inline_if_original:e3sgY29udHJpYnV0b3IubmFtZSBpZiBjb250cmlidXRvci5uYW1lIGVsc2UgIihuYW1lIG5vdCBnaXZlbikiIH19 #}{% if contributor.name %}{{ contributor.name }}{% else %}（姓名尚未提供）{% endif %}{# __tr_block_0001:end #}{# __tr_inline_if_original:end #}</strong></span>
      {%- if contributor.email and contributor.orcid %}
        <br>{{ macros.formatEmail(contributor.email) }}, {{ macros.formatOrcid(contributor.orcid) }}
      {%- elif contributor.email %}
        <br>{{ macros.formatEmail(contributor.email) }}
      {%- elif contributor.orcid %}
        <br>{{ macros.formatOrcid(contributor.orcid) }}
      {%- endif -%}
      {%- if contributor.roles|length > 0 %}
        <br>{% if contributor.roles|length == 0 %}{# __tr_block_0002:start #}角色{# __tr_block_0002:end #}{% else %}{# __tr_block_0003:start #}角色{# __tr_block_0003:end #}{% endif %}：{% for role in contributor.roles %}<span class="role">{{ role }}</span>{% if not loop.last %}、{% endif %}{% endfor %}
      {%- endif %}
      {%- if contributor.affiliation %}
        <br>{# __tr_block_0004:start #}所屬機構： {# __tr_block_0004:end #}<span class="affiliation">{{ macros.integrationROR(contributor.affiliation) }}</span>
      {%- endif %}
    </li>
  {% endfor %}
  </ul>
  {%- elif dc.project.created_by -%}
  <ul>
    {# __tr_block_0005:start #}<li class="contributor">
      <span class="name">{{ dc.project.created_by.first_name }} {{ dc.project.created_by.last_name }}</span>
      <br>{{ macros.formatEmail(dc.project.created_by.email) }}
      {%- if dc.project.created_by.affiliation %}
      <br>所屬機構：<span class="affiliation">{{ dc.project.created_by.affiliation }}</span>
      {%- endif %}
    </li>{# __tr_block_0005:end #}
  </ul>
  {%- else -%}
  <div style="font-style:italic;">{# __tr_block_0006:start #}本資料管理方案尚未描述貢獻者。{# __tr_block_0006:end #}</div>
  {%- endif -%}
</div>{% endif %}

{#- Project or projects (based on number) -#}
{%- set projectsPath = [uuids.adminDetailsCUuid, uuids.projectsQUuid]|reply_path -%}
{%- set projectsItems = repliesMap[projectsPath]|reply_items -%}
{%- set projects = "專案" -%}
{%- set projectsIsAre = "為" -%}

@font-face { font-family: "Pilot CJK"; src: url("data:font/ttf;base64,{{ assets("src/fonts/PilotTC.ttf").data_base64 }}") format("truetype"); }
html body { font-family: "DejaVu Sans", "Pilot CJK", sans-serif; }
/* Owned layout layer; upstream styles remain separately reviewable. */
@page { size: A4; margin: 20mm 19mm 22mm; }
@page {
  @bottom-left { border-top: none; }
  @bottom-center { margin-top: 4mm; padding-top: 2mm; border-top: 1px solid #8c999e; }
}
html body { font-size: 10.5pt; line-height: 1.5; color: #222; }
html body h1 { font-size: 21pt; line-height: 1.25; }
html body h2 { font-size: 15pt; line-height: 1.35; margin: 1.3em 0 .65em; }
html body h3 { font-size: 11pt; font-weight: normal; line-height: 1.5; margin: .9em 0 .6em; color: #47565c; }
html body h4 { font-size: 11.5pt; margin: .85em 0 .4em; }
html body h5 { font-size: 10.5pt; margin: .75em 0 .3em; }
html body h1, html body h2, html body h3, html body h4, html body h5 { break-after: avoid; break-inside: avoid; }
html body p { margin: 0 0 .5em; orphans: 2; widows: 2; }
html body li { margin-bottom: .6em; }
html body li > strong:first-child { display: block; break-after: avoid; }
html body ul { padding-left: 1.4em; margin: .4em 0 .8em; }
html body .answer-detail { margin: .3em 0 .75em; }
html body .answer-detail > p:first-child { break-after: avoid; }
html body .answer-lead { break-after: avoid; }
html body a { overflow-wrap: anywhere; word-break: break-word; color: #185778; }
html body table { border-collapse: collapse; width: 100%; margin: .6em 0; }
html body th, html body td { border: 1px solid #bcc6cc; padding: .4em .5em; vertical-align: top; }
html body th { background: #eef2f4; text-align: left; }
html body thead { display: table-header-group; }
html body tr { break-inside: avoid; }
html body header { height: auto; min-height: 0; padding-top: 0; page-break-after: auto; }
html body header h1 { margin-top: .3em; margin-bottom: .5em; }
html body dl { margin: .6em 0; }
html body dt, html body dd { padding: 6px 10px; }
html body dl dd ul li { margin-bottom: 0; }
html body header div { position: static; }
html body header .note { margin-top: .6em; }
html body header .contact-orcid { white-space: normal; }
html body #dmp-contributors, html body #dmp-projects { page-break-before: auto; }
html body .abstract { page-break-after: auto; }
html body .abstract p { text-align: left; }
html body section { margin-bottom: 1.4em; }
html body .dmp-section .question + .question { margin-top: 1.3em; }
html body .data-gap { padding: .45em .65em; border-left: 3px solid #95651b; background: #fff8e8; }

/* Reading units, not arbitrary fixed-height pages. */
html body #dmp-content { break-before: page; }
html body #dmp-projects h3 { font-size: 14pt; font-weight: bold; color: #222; }
html body .document-meta { font-size: 9pt; color: #526169; }
html body .document-kind { font-size: 14pt; color: #526169; }
html body .document-provenance { border-top: 1px solid #bcc6cc; margin-top: 2em; padding-top: .7em; font-size: 8.5pt; color: #526169; }
html body .dataset-list { list-style: none; padding-left: 0; }
html body .dataset-list > li { margin: 0 0 1em; }
html body .dataset-list h5 { font-size: 11pt; margin: .8em 0 .35em; }
html body .dataset-source { font-size: 9pt; }
html body .dataset-version { margin: .4em 0; }
html body .dataset-version th { width: 15%; font-weight: normal; }
html body .dataset-version p { margin-bottom: .2em; }
html body .dataset-policy > p { display: inline; margin: 0; }
html body .dataset-policy > p::after { content: ' '; }
html body .dataset-policy { margin: .4em 0 .6em; }
/* Q11 scalar references may wrap, but their original text/href is never edited. */
html body .paper-reference { overflow-wrap: anywhere; word-break: break-word; }
html body .answer-detail ul { margin-top: .2em; }
html body .answer-detail li { margin-bottom: .2em; }
html body .answer-detail ul:has(> li:last-child:nth-child(-n+3)) { break-inside: avoid; }
html body li > p:first-child { break-after: avoid; }
html body .resource-table { font-size: 10pt; table-layout: fixed; }
html body .resource-table col.resource-purpose { width: 57%; }
html body .resource-table col.resource-budget { width: 17%; }
html body .resource-table col.resource-funding { width: 26%; }
html body .resource-table tr { break-inside: auto; }
html body .resource-table:has(tbody > tr:last-child:nth-child(-n+3)) { break-inside: avoid; }
/* Row count alone cannot bound a table's height. Release the whole-table keep
   for Q15 purposes with >=12 direct authored blocks; do not rewrite answers or
   change the short/many-row controls. One huge paragraph is outside this hint. */
html body #q-required-resources .resource-table:has(tbody > tr > td:first-child > .answer-detail > :nth-child(12)) { break-inside: auto; }
html body .resource-table p { margin-bottom: .3em; }
html body .resource-table ul { padding-left: 1.2em; }
html body .resource-table .answer-detail { margin: .25em 0; }
html body .resource-table .data-gap { padding: .2em .35em; }
/* BEGIN short-budget panel: PDF-only, <=3 bounded rows with a budget gap. */
html body .pdf-short-budget col.resource-purpose { width: 49%; }
html body .pdf-short-budget col.resource-budget { width: 25%; }
html body .pdf-short-budget col.resource-funding { width: 26%; }
html body .pdf-short-budget th, html body .pdf-short-budget td { padding-top: .25em; padding-bottom: .25em; }
html body .pdf-short-budget p { margin-bottom: .2em; }
/* END short-budget panel */
/* PDF-only long resource: identity repeats in thead, purpose spans all columns. */
html body #q-required-resources .pdf-resource-reading { break-inside: auto; }
html body .pdf-resource-reading thead td { background: #eef2f4; }
html body .pdf-resource-reading tbody td { border-top: none; }
/* Missing metadata needs room for the original prompt, not a three-line label
   in a 17% column. The full-width purpose and complete-header controls stay as-is. */
html body .pdf-resource-reading:has(thead > tr > td > .data-gap) col.resource-purpose { width: 40%; }
html body .pdf-resource-reading:has(thead > tr > td > .data-gap) col.resource-budget { width: 29%; }
html body .pdf-resource-reading:has(thead > tr > td > .data-gap) col.resource-funding { width: 31%; }
/* Exactly the four fixed, unanswered Q15 facts: bounded prose with no authored
   paragraphs, resource rows or nested details. Keep its question with the group. */
html body #q-required-resources:has(.answer > p.data-gap[data-fact-id="specialist-expertise"]:first-child):has(.answer > p.data-gap[data-fact-id="hardware-software"]:nth-child(2)):has(.answer > p.data-gap[data-fact-id="repository-charges"]:nth-child(3)):has(.answer > p.data-gap[data-fact-id="resources-costing"]:nth-child(4):last-child) { break-inside: avoid; }
/* BEGIN empty-Q15 panel: four fixed gaps, no authored or partially answered content. */
html body #q-required-resources > .answer:has(> p.data-gap[data-fact-id="specialist-expertise"][data-status="missing"]:first-child):has(> p.data-gap[data-fact-id="hardware-software"][data-status="missing"]:nth-child(2)):has(> p.data-gap[data-fact-id="repository-charges"][data-status="missing"]:nth-child(3)):has(> p.data-gap[data-fact-id="resources-costing"][data-status="missing"]:nth-child(4):last-child) { border: 1px solid #8a6d3b; border-left-width: 3px; background: #fff8e8; padding: .45em .65em; }
html body #q-required-resources > .answer:has(> p.data-gap[data-fact-id="specialist-expertise"][data-status="missing"]:first-child):has(> p.data-gap[data-fact-id="hardware-software"][data-status="missing"]:nth-child(2)):has(> p.data-gap[data-fact-id="repository-charges"][data-status="missing"]:nth-child(3)):has(> p.data-gap[data-fact-id="resources-costing"][data-status="missing"]:nth-child(4):last-child) > p.data-gap { border: 0; padding: 0; margin: 0 0 .35em; background: transparent; }
html body #q-required-resources > .answer:has(> p.data-gap[data-fact-id="specialist-expertise"][data-status="missing"]:first-child):has(> p.data-gap[data-fact-id="hardware-software"][data-status="missing"]:nth-child(2)):has(> p.data-gap[data-fact-id="repository-charges"][data-status="missing"]:nth-child(3)):has(> p.data-gap[data-fact-id="resources-costing"][data-status="missing"]:nth-child(4):last-child) > p.data-gap:last-child { margin-bottom: 0; }
/* END empty-Q15 panel */
html body .template-gap { font-size: 9.5pt; color: #526169; border-left-color: #8c999e; background: #f3f5f5; }
/* Owned publication reading blocks: structure, not hidden list markers. */
html body .dataset-section { margin: .6em 0 1em; }
html body .dataset-section > h5 { font-size: 11pt; margin: .5em 0 .35em; }
html body .distribution-section { margin: .35em 0 .65em; }
html body .distribution-section + .distribution-section { border-top: 1px solid #cbd2d5; padding-top: .6em; }
html body .license-entry { margin: .25em 0 .5em; }
html body .license-entry + .license-entry { border-top: 1px dotted #cbd2d5; padding-top: .4em; }
html body .storage-detail-limits li { margin-bottom: .25em; }
/* BEGIN short Q5 context: bounded owned prose and its operational limitations. */
@media print {
html body #q-store-backup > .answer.q5-short-context { break-inside: avoid; }
}
/* END short Q5 context */
/* Narrow reading units, not whole-question keep-together rules. */
html body .short-reading-unit, html body .ethical-data-flags { break-inside: avoid; }
/* Only provenanceReading marks bounded, simple tables; long answers stay free. */
html body .short-table-unit { break-inside: avoid; }
/* Q11 emits this hint only for <=3 bounded, inline-only repository summaries. */
html body .short-repository-list { break-inside: avoid; }
html body .repository-label { font-weight: bold; }
/* Q13: one owned heading, then one contiguous identifier arrangement. */
html body .identifier-heading { margin: .25em 0 .35em; break-after: avoid; }
html body .identifier-heading > p { display: inline; margin: 0; }
html body .identifier-heading > p::after { content: ' '; }
html body .reading-gap { margin: .5em 0; }
html body .reading-gap > p { margin-bottom: 0; }
html body .answer-reference { font-size: 9.5pt; color: #526169; margin-top: .7em; }
html body .data-gap[data-status="missing-output"] { border: none; border-left: 2px solid #b5bec1; background: #f5f6f6; color: #526169; font-size: 10pt; padding: .4em .65em; }
.quantity { white-space: nowrap; }
.date-value { white-space: nowrap; }
/* Only fixed access / simple repository / standard licence facts join in Q10.
   Restricted terms, complex repositories, missing answers and labels stay blocks. */
.distribution-reading-unit > p:not(.data-gap):not(.answer-lead),
.distribution-reading-unit > .joined-policy,
.distribution-reading-unit .joined-policy > p,
.distribution-reading-unit .joined-policy > .answer-lead,
.distribution-reading-unit .joined-policy .license-summary,
.distribution-reading-unit .joined-policy > .answer-lead > p { display: inline; margin: 0; }
.distribution-reading-unit > p:not(.data-gap):not(.answer-lead)::after,
.distribution-reading-unit .joined-policy p::after { content: " "; }
/* BEGIN identifier CJK separator: fixed Q13 sentences only, not headings. */
html[lang="zh-Hant"] body .identifier-arrangement.dataset-policy > p::after { content: none; }
/* END identifier CJK separator */
/* BEGIN archive gap pairs: print-only, adjacent fixed missing facts, two per panel. */
@media print {
