{# PDF-only presentation, shared facts and translated fragments stay in Q15. #}
{%- set pdf_budget_reading = true -%}
{%- set pdfDocument -%}{%- include 'src/index.html.j2' -%}{%- endset -%}
{%- import 'src/pdf/short-resources.html.j2' as shortResources -%}
{{- shortResources.document(pdfDocument) -}}

{# PDF-only: bounded rows in an ordinary 4..32-row table. Original captured
   fragments remain authoritative. No whole-table keep or prose reconstruction. #}
{%- macro classify(row, result) -%}
  {%- set result.ok = true -%}
  {%- set fixed = [
    'div class="answer-detail"',
    'div class="answer-detail" data-fact-id="resource-justification" data-status="complete"',
    'p class="data-gap" data-requirement-id="SE-6b" data-fact-id="resource-justification" data-status="missing"',
    'p class="data-gap" data-requirement-id="SE-6b" data-fact-id="resource-allocation" data-status="missing"',
    'p data-fact-id="resource-amount-value" data-status="complete"',
    'p data-fact-id="resource-currency" data-status="complete"',
    'p class="data-gap" data-requirement-id="SE-6b" data-fact-id="resource-amount" data-status="missing"',
    'p data-fact-id="cost-coverage" data-status="complete"',
    'p class="data-gap" data-fact-id="grant-number" data-status="missing"',
    'p class="data-gap" data-requirement-id="SE-6b" data-fact-id="cost-coverage" data-status="missing"'
  ] -%}
  {%- for value, limit, paragraphs, tokenLimit in [(row.title, 80, 1, 40), (row.purpose, 240, 3, 40), (row.budget, 80, 3, 12), (row.funding, 100, 3, 20)] -%}
    {%- set visible = (value|striptags).split()|join(' ') -%}
    {%- set size = namespace(width=0, token=0) -%}
    {%- if not visible or value|length > 3000 or not 1 <= value.count('<p') <= paragraphs -%}{%- set result.ok = false -%}{%- endif -%}
    {%- for character in visible -%}
      {%- set size.width = size.width + (2 if character >= '⺀' else 1) -%}
      {%- set size.token = 0 if character >= '⺀' or character in ' -/' else size.token + 1 -%}
      {%- if size.token > tokenLimit -%}{%- set result.ok = false -%}{%- endif -%}
    {%- endfor -%}
    {%- if size.width > limit -%}{%- set result.ok = false -%}{%- endif -%}
    {%- set stack = [] -%}
    {%- if value.split('<', 1)[0]|trim -%}{%- set result.ok = false -%}{%- endif -%}
    {%- for fragment in value.split('<')[1:] -%}
      {%- set tag = fragment.split('>', 1)[0] -%}
      {%- set content = fragment.split('>', 1)[-1] -%}
      {%- set name = tag.split(' ', 1)[0] -%}
      {%- if tag.startswith('/') -%}
        {%- if stack and stack[-1] == tag[1:] -%}{%- do stack.pop() -%}
        {%- else -%}{%- set result.ok = false -%}{%- endif -%}
      {%- else -%}
        {%- if tag not in ['p', 'strong', 'em', 'code'] and tag not in fixed -%}{%- set result.ok = false -%}{%- endif -%}
        {%- set parent = stack[-1] if stack else '' -%}
        {%- if (name == 'div' and parent != '') or (name == 'p' and parent not in ['', 'div']) or (name in ['strong', 'em', 'code'] and parent != 'p') -%}{%- set result.ok = false -%}{%- endif -%}
        {%- do stack.append(name) -%}
      {%- endif -%}
      {%- if content|trim and (not stack or stack[-1] not in ['p', 'strong', 'em', 'code']) -%}{%- set result.ok = false -%}{%- endif -%}
    {%- endfor -%}
    {%- if stack -%}{%- set result.ok = false -%}{%- endif -%}
  {%- endfor -%}
{%- endmacro -%}

{%- macro table(original, rows) -%}
  {%- set result = namespace(value=original) -%}
  {%- if 4 <= rows|length <= 32 and original.count('<table class="resource-table">') == 1 and original.count('<tr data-item-id=') == rows|length -%}
    {%- for row in rows -%}
      {%- set eligible = namespace(ok=false) -%}
      {{- classify(row, eligible) -}}
      {%- set identity = row.id if row.id is string else '' -%}
      {%- if not 1 <= identity|length <= 256 -%}{%- set eligible.ok = false -%}{%- endif -%}
      {%- for character in identity -%}{%- if character not in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-._' -%}{%- set eligible.ok = false -%}{%- endif -%}{%- endfor -%}
      {%- set opening = '<tr data-item-id="' + identity + '">' -%}
      {%- if eligible.ok and row.original is string and (row.original|trim).startswith(opening) and (row.original|trim).endswith('</tr>') and row.original.count('<td>') == row.original.count('</td>') == 3 and original.count(row.original) == 1 and original.count(opening) == 1 -%}
        {%- set hint = '<tr data-item-id="' + identity + '" class="pdf-short-resource-row" style="break-inside: avoid">' -%}
        {%- set replacement = row.original|replace(opening, hint|safe, 1) -%}
        {%- set result.value = result.value|replace(row.original, replacement|safe, 1) -%}
      {%- endif -%}
    {%- endfor -%}
  {%- endif -%}
  {{- result.value -}}
{%- endmacro -%}

{# PDF-entry presentation only. Preserve every input byte except the unique
   owned Q15 opening tag. Conservative grammar/size rejection is intentional. #}
{%- macro measure(value, result, limit) -%}
  {%- set visible = (value|striptags).split()|join(' ') -%}
  {%- set result.width = 0 -%}
  {%- for character in visible -%}{%- set result.width = result.width + (2 if character >= '⺀' else 1) -%}{%- endfor -%}
  {%- if not visible or result.width > limit -%}{%- set result.ok = false -%}{%- endif -%}
{%- endmacro -%}

{%- macro document(original) -%}
  {%- set opening = '<div id="q-required-resources" class="question" data-requirement-id="SE-6b">' -%}
  {%- set hint = '<div id="q-required-resources" class="question pdf-short-resources" style="break-inside: avoid" data-requirement-id="SE-6b">' -%}
  {%- set selection = namespace(ok=false, width=0) -%}
  {%- if original.count(opening) == 1 -%}
    {%- set tail = original.split(opening, 1)[1] -%}
    {%- if tail.count('</section>') == 1 -%}
      {%- set question = (opening|safe) + (tail.split('</section>', 1)[0]|safe) -%}
      {%- set selection.ok = question|length <= 16000 and question.count('<div class="project-resources" ') == 1 and question.count('<table ') == 1 and question.count('<h3>') == 1 and question.count('<h4>') == 1 and question.count('<thead>') == 1 and question.count('<tbody>') == 1 and question.count('<th ') == 3 and 1 <= question.count('<tr data-item-id=') <= 2 and question.count('<ul>') <= 1 and question.count('<li>') <= 2 and question.count('<p') <= 16 -%}
      {%- if selection.ok -%}
      {%- if question.count('<div class="answer">') != 1 or not question[opening|length:].lstrip().startswith('<h3>') or question.split('</table>', 1)[-1]|replace('</div>', '')|trim -%}{%- set selection.ok = false -%}{%- endif -%}
      {%- if question.count('<colgroup>') != 1 or not question.find('<colgroup>') < question.find('<thead>') < question.find('<tbody>') -%}{%- set selection.ok = false -%}{%- endif -%}
      {%- for column in ['resource-purpose', 'resource-budget', 'resource-funding'] -%}{%- if question.count('<col class="' + column + '">') != 1 -%}{%- set selection.ok = false -%}{%- endif -%}{%- endfor -%}
      {%- if not question.find('<col class="resource-purpose">') < question.find('<col class="resource-budget">') < question.find('<col class="resource-funding">') -%}{%- set selection.ok = false -%}{%- endif -%}
      {{- measure(question, selection, 1200) -}}
      {%- set stack = [] -%}
      {%- set plain = ['p', 'strong', 'em', 'code', 'ul', 'li', 'h3', 'h4', 'colgroup', 'thead', 'tbody', 'tr', 'td'] -%}
      {%- set fixed = [
        opening[1:-1], 'div class="answer"', 'div class="answer-lead"',
        'div class="answer-detail" data-fact-id="specialist-expertise-detail" data-status="complete"',
        'div class="answer-detail" data-fact-id="resource-justification" data-status="complete"',
        'div class="answer-detail"',
        'p data-requirement-id="SE-6b" data-fact-id="specialist-expertise" data-status="complete"',
        'p data-requirement-id="SE-6b" data-fact-id="specialist-expertise" data-status="explicit-no"',
        'p data-requirement-id="SE-6b" data-fact-id="hardware-software" data-status="explicit-no"',
        'table class="resource-table"', 'th scope="col"',
        'span data-fact-id="repository-charges" data-status="complete"',
        'col class="resource-purpose"', 'col class="resource-budget"', 'col class="resource-funding"'
      ] -%}
      {%- for fragment in question.split('<')[1:] -%}
        {%- set tag = fragment.split('>', 1)[0] -%}
        {%- set content = fragment.split('>', 1)[-1] -%}
        {%- set name = tag.split(' ', 1)[0] -%}
        {%- if tag.startswith('/') -%}
          {%- if stack and stack[-1].split(' ', 1)[0] == tag[1:] -%}{%- do stack.pop() -%}
          {%- else -%}{%- set selection.ok = false -%}{%- endif -%}
        {%- else -%}
          {%- set dynamic = namespace(ok=false) -%}
          {%- for prefix in ['div class="project-resources" data-item-id="', 'tr data-item-id="'] -%}
            {%- if tag.startswith(prefix) and tag.endswith('"') -%}
              {%- set identity = tag[prefix|length:-1] -%}
              {%- set dynamic.ok = identity|length > 0 -%}
              {%- for character in identity -%}{%- if character not in '0123456789abcdef-.' -%}{%- set dynamic.ok = false -%}{%- endif -%}{%- endfor -%}
            {%- endif -%}
          {%- endfor -%}
          {%- if tag not in plain and tag not in fixed and not dynamic.ok -%}{%- set selection.ok = false -%}{%- endif -%}
          {%- set parent = stack[-1] if stack else '' -%}
          {%- set parentName = parent.split(' ', 1)[0] -%}
          {%- set legal = namespace(ok=false) -%}
          {%- if tag == opening[1:-1] -%}{%- set legal.ok = not stack -%}
          {%- elif tag == 'div class="answer"' or name == 'h3' -%}{%- set legal.ok = parent == opening[1:-1] -%}
          {%- elif name == 'div' -%}
            {%- set legal.ok = (parent == 'div class="answer"' and (dynamic.ok or tag in [fixed[2], fixed[3]])) or (parent == 'td' and tag in [fixed[4], fixed[5]]) -%}
          {%- elif name == 'h4' -%}{%- set legal.ok = parent == 'div class="answer"' -%}
          {%- elif name == 'table' -%}{%- set legal.ok = parent.startswith('div class="project-resources" data-item-id="') -%}
          {%- elif name in ['colgroup', 'thead', 'tbody'] -%}{%- set legal.ok = parent == 'table class="resource-table"' -%}
          {%- elif name == 'col' -%}{%- set legal.ok = parent == 'colgroup' -%}
          {%- elif name == 'tr' -%}{%- set legal.ok = (tag == 'tr' and parent == 'thead') or (dynamic.ok and parent == 'tbody') -%}
          {%- elif name == 'th' -%}{%- set legal.ok = parent == 'tr' -%}
          {%- elif name == 'td' -%}{%- set legal.ok = parent.startswith('tr data-item-id="') -%}
          {%- elif name == 'p' -%}{%- set legal.ok = parentName == 'div' and parent != opening[1:-1] and not parent.startswith('div class="project-resources"') or parent == 'td' -%}
          {%- elif name == 'span' -%}{%- set legal.ok = parent == 'p data-requirement-id="SE-6b" data-fact-id="hardware-software" data-status="explicit-no"' and question.count('<span ') == 1 -%}
          {%- elif name in ['strong', 'em', 'code'] -%}{%- set legal.ok = parentName in ['p', 'li'] -%}
          {%- elif name == 'ul' -%}{%- set legal.ok = parent == fixed[3] -%}
          {%- elif name == 'li' -%}{%- set legal.ok = parent == 'ul' -%}
          {%- endif -%}
          {%- if not legal.ok -%}{%- set selection.ok = false -%}{%- endif -%}
          {%- if name != 'col' -%}{%- do stack.append(tag) -%}{%- endif -%}
        {%- endif -%}
        {%- if content|trim and (not stack or stack[-1].split(' ', 1)[0] not in ['p', 'span', 'strong', 'em', 'code', 'li', 'h3', 'h4', 'th']) -%}{%- set selection.ok = false -%}{%- endif -%}
      {%- endfor -%}
      {%- if stack -%}{%- set selection.ok = false -%}{%- endif -%}
      {%- for paragraph in question.split('<p')[1:] -%}{{- measure(paragraph.split('>', 1)[-1].split('</p>', 1)[0], selection, 160) -}}{%- endfor -%}
      {%- for item in question.split('<li>')[1:] -%}{{- measure(item.split('</li>', 1)[0], selection, 80) -}}{%- endfor -%}
      {%- for tag, limit in [('h3', 360), ('h4', 80), ('th scope="col"', 40)] -%}
        {%- for value in question.split('<' + tag + '>')[1:] -%}{{- measure(value.split('</' + tag.split(' ', 1)[0] + '>', 1)[0], selection, limit) -}}{%- endfor -%}
      {%- endfor -%}
      {%- for row in question.split('<tr data-item-id=')[1:] -%}{%- if row.split('</tr>', 1)[0].count('<td>') != 3 -%}{%- set selection.ok = false -%}{%- endif -%}{%- endfor -%}
      {%- for cell in question.split('<td>')[1:] -%}
        {%- set value = cell.split('</td>', 1)[0] -%}
        {%- set column = loop.index0 % 3 -%}
        {{- measure(value, selection, [300, 40, 80][column]) -}}
        {%- if value.count('<p') != [3, 1, 1][column] -%}{%- set selection.ok = false -%}{%- endif -%}
      {%- endfor -%}
      {%- if question.count('<td>') != 3 * question.count('<tr data-item-id=') -%}{%- set selection.ok = false -%}{%- endif -%}
      {%- endif -%}
    {%- endif -%}
  {%- endif -%}
  {%- if selection.ok -%}
    {{- original|replace(opening, hint|safe, 1) -}}
  {%- else -%}{{- original -}}{%- endif -%}
{%- endmacro -%}

{# Project-wide cold storage after the project; not a dataset's publication repository. #}
{% set archivePath = [uuids.preservingCUuid, uuids.archivedAfterQUuid]|reply_path %}
{% set archive = repliesMap[archivePath]|reply_str_value %}
{% if archive in [uuids.archivedAfterYesAUuid, uuids.archivedAfterNoAUuid] %}
<div class="post-project-archive" data-scope="project">
{# __tr_block_0000:start #}<h4>計畫結束後的冷儲存安排（計畫層級）</h4>{# __tr_block_0000:end #}
<div class="dataset-policy">
{% if archive == uuids.archivedAfterNoAUuid %}
  {# __tr_block_0001:start #}<p data-fact-id="post-project-archive" data-status="explicit-no">本計畫結束後不採用冷儲存；這項回答並不排除其他保存方式。</p>{# __tr_block_0001:end #}
{% else %}
  {# __tr_block_0002:start #}<p data-fact-id="post-project-archive" data-status="complete">本計畫結束後，將以冷儲存方式保存資料副本。</p>{# __tr_block_0002:end #}
  {% set archivePrefix = [archivePath, uuids.archivedAfterYesAUuid]|reply_path %}
  {% set payer = repliesMap[[archivePrefix, uuids.archivedAfterPayerQUuid]|reply_path]|reply_str_value %}
  {% if payer == uuids.archivedAfterPayerGrantAUuid %}
    {# __tr_block_0003:start #}<p data-fact-id="archive-payer" data-status="complete">這項長期儲存費用將由研究補助經費支付。</p>{# __tr_block_0003:end #}
  {% elif payer == uuids.archivedAfterPayerDepartmentAUuid %}
    {# __tr_block_0004:start #}<p data-fact-id="archive-payer" data-status="complete">這項長期儲存費用將由一個或多個參與單位的部門預算支付。</p>{# __tr_block_0004:end #}
  {% elif payer == uuids.archivedAfterPayerInstituteAUuid %}
    {# __tr_block_0005:start #}<p data-fact-id="archive-payer" data-status="complete">一個或多個參與機構已編列預算，提供這項長期儲存服務。</p>{# __tr_block_0005:end #}
  {% else %}
    <div class="reading-gap">{# __tr_block_0006:start #}{% if output_profile|default('review') != 'submission' %}<p class="data-gap" data-fact-id="archive-payer" data-status="missing">尚待補充：計畫結束後冷儲存費用的負擔單位。</p>{% endif %}{# __tr_block_0006:end #}</div>
  {% endif %}
  {% set periodPath = [archivePrefix, uuids.archivedAfterPeriodQUuid]|reply_path %}
  {% set period = repliesMap[periodPath]|reply_str_value %}
  {% set years = '' %}
  {% if period == uuids.archivedAfterPeriodFiveAUuid %}{% set years = '5' %}
  {% elif period == uuids.archivedAfterPeriodTenAUuid %}{% set years = '10' %}
  {% elif period == uuids.archivedAfterPeriodFifteenAUuid %}{% set years = '15' %}
  {% elif period == uuids.archivedAfterPeriodYearsAUuid %}
    {% set years = repliesMap[[periodPath, uuids.archivedAfterPeriodYearsAUuid, uuids.archivedAfterYearsQUuid]|reply_path]|reply_str_value %}
  {% endif %}
  {% if years|trim %}
    {% set archiveDuration %}{# __tr_block_0007:start #}{{ macros.quantity(years, '年') }}{# __tr_block_0007:end #}{% endset %}
    {# __tr_block_0008:start #}<p data-fact-id="archive-minimum-period" data-status="complete">典藏資料將至少保留 {{ archiveDuration }}。</p>{# __tr_block_0008:end #}
  {% elif period == uuids.archivedAfterPeriodOtherAUuid %}
    <div class="answer-lead">{# __tr_block_0009:start #}<p>典藏資料最低保存期限的其他安排：</p>{# __tr_block_0009:end #}</div>
    {% set arrangement = repliesMap[[periodPath, uuids.archivedAfterPeriodOtherAUuid, uuids.archivedAfterPeriodOtherQUuid]|reply_path]|reply_str_value %}
    {% if arrangement|trim %}
      <div class="answer-detail" data-fact-id="archive-minimum-period" data-status="complete">{{ arrangement|markdown }}</div>
    {% else %}
      <div class="reading-gap">{# __tr_block_0010:start #}{% if output_profile|default('review') != 'submission' %}<p class="data-gap" data-fact-id="archive-minimum-period" data-status="missing">尚待補充：典藏資料最低保存期限的其他安排。</p>{% endif %}{# __tr_block_0010:end #}</div>
    {% endif %}
  {% else %}
    <div class="reading-gap">{# __tr_block_0011:start #}{% if output_profile|default('review') != 'submission' %}<p class="data-gap" data-fact-id="archive-minimum-period" data-status="missing">尚待補充：典藏資料的最低保存期限。</p>{% endif %}{# __tr_block_0011:end #}</div>
  {% endif %}
  {% set extensionPath = [archivePrefix, uuids.archivedAfterExtendQUuid]|reply_path %}
  {% set extension = repliesMap[extensionPath]|reply_str_value %}
  {% if extension == uuids.archivedAfterExtendNoAUuid %}
    {# __tr_block_0012:start #}<p data-fact-id="archive-extension" data-status="explicit-no">典藏資料的保存期限無法延長。</p>{# __tr_block_0012:end #}
    {% set limit = repliesMap[[extensionPath, uuids.archivedAfterExtendNoAUuid, uuids.archivedAfterExtendNoReasonQUuid]|reply_path]|reply_str_value %}
    {% if limit == uuids.archivedAfterExtendNoLegalAUuid %}
      {# __tr_block_0013:start #}<p data-fact-id="archive-extension-limit" data-status="complete">保存期限受到法律或契約限制。</p>{# __tr_block_0013:end #}
    {% elif limit == uuids.archivedAfterExtendNoBudgetAUuid %}
      {# __tr_block_0014:start #}<p data-fact-id="archive-extension-limit" data-status="complete">保存期限受到預算限制。</p>{# __tr_block_0014:end #}
    {% else %}
      <div class="reading-gap">{# __tr_block_0015:start #}{% if output_profile|default('review') != 'submission' %}<p class="data-gap" data-fact-id="archive-extension-limit" data-status="missing">尚待補充：典藏資料保存期限無法延長的原因。</p>{% endif %}{# __tr_block_0015:end #}</div>
    {% endif %}
  {% elif extension == uuids.archivedAfterExtendYesAUuid %}
    {# __tr_block_0016:start #}<p data-fact-id="archive-extension" data-status="complete">典藏資料的保存期限可以延長。</p>{# __tr_block_0016:end #}
    {% set authority = repliesMap[[extensionPath, uuids.archivedAfterExtendYesAUuid, uuids.archivedAfterExtendWhoQUuid]|reply_path]|reply_str_value %}
    {% if authority == uuids.archivedAfterExtendWhoPiAUuid %}
      {# __tr_block_0017:start #}<p data-fact-id="archive-extension-authority" data-status="complete">是否延長保存期限，將由參與本計畫的一位計畫主持人決定。</p>{# __tr_block_0017:end #}
    {% elif authority == uuids.archivedAfterExtendWhoArchiveAUuid %}
      {# __tr_block_0018:start #}<p data-fact-id="archive-extension-authority" data-status="complete">是否延長保存期限，將由圖書館或典藏單位人員決定。</p>{# __tr_block_0018:end #}
    {% else %}
      <div class="reading-gap">{# __tr_block_0019:start #}{% if output_profile|default('review') != 'submission' %}<p class="data-gap" data-fact-id="archive-extension-authority" data-status="missing">尚待補充：決定是否延長保存期限的人員或單位。</p>{% endif %}{# __tr_block_0019:end #}</div>
    {% endif %}
    {% set basis = repliesMap[[extensionPath, uuids.archivedAfterExtendYesAUuid, uuids.archivedAfterExtendBasisQUuid]|reply_path]|reply_items %}
    {# Only the three fixed choices form a sentence; no authored blocks join it.
       Capture translated spans before joining, retaining each choice's fact. #}
    {% set basisItems = [] %}
    {% set basisChoices = [uuids.archivedAfterExtendBasisActualChoiceUuid, uuids.archivedAfterExtendBasisPredictedChoiceUuid, uuids.archivedAfterExtendBasisBudgetChoiceUuid] %}
    {% if uuids.archivedAfterExtendBasisActualChoiceUuid in basis %}
      {% set basisItem %}<span data-fact-id="archive-extension-actual-use" data-status="complete">{# __tr_block_0020:start #}典藏資料的實際使用情況{# __tr_block_0020:end #}</span>{% endset %}
      {% do basisItems.append(basisItem) %}
    {% endif %}
    {% if uuids.archivedAfterExtendBasisPredictedChoiceUuid in basis %}
      {% set basisItem %}<span data-fact-id="archive-extension-predicted-use" data-status="complete">{# __tr_block_0021:start #}典藏資料的預期使用情況{# __tr_block_0021:end #}</span>{% endset %}
      {% do basisItems.append(basisItem) %}
    {% endif %}
    {% if uuids.archivedAfterExtendBasisBudgetChoiceUuid in basis %}
      {% set basisItem %}<span data-fact-id="archive-extension-budget" data-status="complete">{# __tr_block_0022:start #}可用預算{# __tr_block_0022:end #}</span>{% endset %}
      {% do basisItems.append(basisItem) %}
    {% endif %}
    {% if basisItems %}
      <div class="archive-extension-basis-summary">{# __tr_block_0023:start #}<p>延長保存期限的考量因素：{{ basisItems|join("、") }}。</p>{# __tr_block_0023:end #}</div>
    {% endif %}
    {% if not basis %}
      <div class="reading-gap">{# __tr_block_0024:start #}{% if output_profile|default('review') != 'submission' %}<p class="data-gap" data-fact-id="archive-extension-basis" data-status="missing">尚待補充：決定是否延長保存期限的依據。</p>{% endif %}{# __tr_block_0024:end #}</div>
    {% elif basis|reject("in", basisChoices)|list %}
      <div class="reading-gap">{# __tr_block_0025:start #}{% if output_profile|default('review') != 'submission' %}<p class="data-gap" data-fact-id="archive-extension-basis" data-status="needs-review">部分已選取的延長保存期限考量因素無法由本模板辨識，請核對填答內容。</p>{% endif %}{# __tr_block_0025:end #}</div>
    {% endif %}
  {% else %}
    <div class="reading-gap">{# __tr_block_0026:start #}{% if output_profile|default('review') != 'submission' %}<p class="data-gap" data-fact-id="archive-extension" data-status="missing">尚待補充：典藏資料的保存期限能否延長。</p>{% endif %}{# __tr_block_0026:end #}</div>
  {% endif %}
  {% set formats = repliesMap[[archivePrefix, uuids.archivedAfterFormatsQUuid]|reply_path]|reply_str_value %}
  {% if formats == uuids.archivedAfterFormatsYesAUuid %}
    {# __tr_block_0027:start #}<p data-fact-id="archive-format-migration" data-status="complete">冷儲存中的資料格式若已過時，將予以更新。</p>{# __tr_block_0027:end #}
  {% elif formats == uuids.archivedAfterFormatsNoAUuid %}
    {# __tr_block_0028:start #}<p data-fact-id="archive-format-migration" data-status="explicit-no">冷儲存中的資料格式即使過時，也不會更新。</p>{# __tr_block_0028:end #}
  {% else %}
    <div class="reading-gap">{# __tr_block_0029:start #}{% if output_profile|default('review') != 'submission' %}<p class="data-gap" data-fact-id="archive-format-migration" data-status="missing">尚待補充：冷儲存中過時資料格式的處理方式。</p>{% endif %}{# __tr_block_0029:end #}</div>
  {% endif %}
  {% set media = repliesMap[[archivePrefix, uuids.archivedAfterMediaQUuid]|reply_path]|reply_str_value %}
  {% if media == uuids.archivedAfterMediaYesAUuid %}
    {# __tr_block_0030:start #}<p data-fact-id="archive-media-migration" data-status="complete">典藏資料將定期移轉至較新的儲存媒體。</p>{# __tr_block_0030:end #}
  {% elif media == uuids.archivedAfterMediaNoAUuid %}
    {# __tr_block_0031:start #}<p data-fact-id="archive-media-migration" data-status="explicit-no">典藏資料不會定期移轉至較新的儲存媒體。</p>{# __tr_block_0031:end #}
  {% else %}
    <div class="reading-gap">{# __tr_block_0032:start #}{% if output_profile|default('review') != 'submission' %}<p class="data-gap" data-fact-id="archive-media-migration" data-status="missing">尚待補充：典藏資料移轉至較新儲存媒體的安排。</p>{% endif %}{# __tr_block_0032:end #}</div>
  {% endif %}
{% endif %}
</div>
</div>
{% endif %}

{# Included inside Q11's dataset-policy. Only direct owned paragraphs may join.
   Description and stage are context, not evidence of preservation decisions. #}
{% set producedDescription = repliesMap[[pathPrefix, uuids.producedDataDescriptionQUuid]|reply_path]|reply_str_value %}
{% if producedDescription|trim %}
  <div class="answer-detail" data-fact-id="preservation-dataset-description" data-status="complete">{{ producedDescription|markdown }}</div>
{% endif %}
{% set stagePath = [pathPrefix, uuids.producedDataStageQUuid]|reply_path %}
{% set stage = repliesMap[stagePath]|reply_str_value %}
{% if stage == uuids.producedDataStageRawAUuid %}
  {# __tr_block_0000:start #}<p data-fact-id="preservation-data-stage" data-status="complete">此資料集包含原始資料。</p>{# __tr_block_0000:end #}
{% elif stage == uuids.producedDataStageIntermediateAUuid %}
  {# __tr_block_0001:start #}<p data-fact-id="preservation-data-stage" data-status="complete">此資料集包含中間處理資料。</p>{# __tr_block_0001:end #}
{% elif stage == uuids.producedDataStageUnpublishableAUuid %}
  {# __tr_block_0002:start #}<p data-fact-id="preservation-data-stage" data-status="complete">此資料集包含經處理的資料，其研究結果無法發表。</p>{# __tr_block_0002:end #}
{% elif stage == uuids.producedDataStagePublishedAUuid %}
  {# __tr_block_0003:start #}<p data-fact-id="preservation-data-stage" data-status="complete">此資料集包含經處理的資料，其研究結果已發表。</p>{# __tr_block_0003:end #}
{% endif %}

{# A reference is not a preservation decision. Keep its full scalar value outside
   the owned policy run, and gate it by its own stage question, not publication. #}
{% set paperStagePath = [pathPrefix, uuids.producedDataStageQUuid]|reply_path %}
{% if repliesMap[paperStagePath]|reply_str_value == uuids.producedDataStagePublishedAUuid %}
  {% set paper = repliesMap[[paperStagePath, uuids.producedDataStagePublishedAUuid, uuids.producedDataPaperQUuid]|reply_path]|reply_str_value %}
  {% if paper|trim %}
    {# Conservative whole-value HTTP(S) linking, not URL extraction or repair.
       Never shorten the displayed value or append template punctuation to it. #}
    {% set paperLink = namespace(eligible=false) %}
    {% if (paper.startswith('https://') or paper.startswith('http://')) and paper.split()|join('') == paper and '<' not in paper and '>' not in paper and '"' not in paper and '\\' not in paper %}
      {% set authority = paper.split('://', 1)[1].split('/', 1)[0].split('?', 1)[0].split('#', 1)[0] %}
      {% set paperLink.eligible = authority|length > 0 and '@' not in authority %}
    {% endif %}
    {# Capture the translatable label separately from the conditional value markup. #}
    {% set paperLabel %}<span class="paper-reference-label">{# __tr_block_0000:start #}相關論文：{# __tr_block_0000:end #}</span>{% endset %}
    <div class="paper-reference" data-fact-id="preservation-related-paper" data-status="complete"><p>{{ paperLabel }} <span class="paper-reference-value">{% if paperLink.eligible %}<a href="{{ paper|e }}">{{ paper|e }}</a>{% else %}{{ paper|e }}{% endif %}</span></p></div>
  {% endif %}
{% endif %}

{# This branch is a publication decision, never proof of destruction/non-preservation. #}
{% set reasonPath = [isPublishedDataPath, uuids.isPublishedDataNoAUuid, uuids.notPublishedReasonQUuid]|reply_path %}
{% set reason = repliesMap[reasonPath]|reply_str_value %}
{% if reason == uuids.notPublishedReasonRawAUuid %}
  {# __tr_block_0000:start #}<p data-fact-id="nonpublication-reason" data-status="complete">依問卷填答，不發布的原因是這些原始資料不需再次處理。</p>{# __tr_block_0000:end #}
{% elif reason == uuids.notPublishedReasonResultsAUuid %}
  {# __tr_block_0001:start #}<p data-fact-id="nonpublication-reason" data-status="complete">依問卷填答，不發布的原因是此資料集僅產出無法發表的研究結果。</p>{# __tr_block_0001:end #}
{% elif reason == uuids.notPublishedReasonIntermediateAUuid %}
  {# __tr_block_0002:start #}<p data-fact-id="nonpublication-reason" data-status="complete">依問卷填答，不發布的原因是這些中間處理資料容易重製。</p>{# __tr_block_0002:end #}
{% elif reason == uuids.notPublishedReasonNoReuseAUuid %}
  {# __tr_block_0003:start #}<p data-fact-id="nonpublication-reason" data-status="complete">依問卷填答，此資料集被認為沒有再次使用的價值，因此不發布。</p>{# __tr_block_0003:end #}
{% elif reason == uuids.notPublishedReasonCostAUuid %}
  {# __tr_block_0004:start #}<p data-fact-id="nonpublication-reason" data-status="complete">依問卷填答，不發布的原因是費用考量。</p>{# __tr_block_0004:end #}
{% elif reason == uuids.notPublishedReasonLostAUuid %}
  {# __tr_block_0005:start #}<p data-fact-id="nonpublication-reason" data-status="complete">依問卷填答，此資料集因已遺失而不發布。</p>{# __tr_block_0005:end #}
{% elif reason == uuids.notPublishedReasonOtherAUuid %}
  <div class="answer-lead">{# __tr_block_0006:start #}<p>此資料集不發布的其他原因：</p>{# __tr_block_0006:end #}</div>
  {% set reasonText = repliesMap[[reasonPath, uuids.notPublishedReasonOtherAUuid, uuids.notPublishedReasonOtherQUuid]|reply_path]|reply_str_value %}
  {% if reasonText|trim %}
    <div class="answer-detail" data-fact-id="nonpublication-reason" data-status="complete">{{ reasonText|markdown }}</div>
  {% else %}
    <div class="reading-gap">{# __tr_block_0007:start #}{% if output_profile|default('review') != 'submission' %}<p class="data-gap" data-fact-id="nonpublication-reason" data-status="missing">尚待補充：此資料集不發布的其他原因。</p>{% endif %}{# __tr_block_0007:end #}</div>
  {% endif %}
{% else %}
  <div class="reading-gap">{# __tr_block_0008:start #}{% if output_profile|default('review') != 'submission' %}<p class="data-gap" data-fact-id="nonpublication-reason" data-status="missing">尚待補充：此資料集不發布的原因。</p>{% endif %}{# __tr_block_0008:end #}</div>
{% endif %}

{%- set projectsPath = [uuids.adminDetailsCUuid, uuids.projectsQUuid]|reply_path -%}
{%- set projectsItems = repliesMap[projectsPath]|reply_items -%}
{% if projectsItems or output_profile|default('review') != 'submission' %}<div id="dmp-projects">
  {# __tr_block_0000:start #}<h2>研究計畫概要</h2>{# __tr_block_0000:end #}

  {% for projectsItem in projectsItems %}
    <div class="project">
    {%- set projectNamePath = [projectsPath, projectsItem, uuids.projectNameQUuid]|reply_path -%}
    {%- set projectName = repliesMap[projectNamePath]|reply_str_value -%}
    {%- if projectName and projectsItems|length > 1 -%}
      <h3>{{ projectName }}</h3>
    {%- elif not projectName -%}
      {# __tr_block_0001:start #}<h3 class="empty-value">（尚未提供專案名稱）</h3>{# __tr_block_0001:end #}
    {%- endif -%}

    {%- set projectNumberPath = [projectsPath, projectsItem, uuids.projectNumberQUuid]|reply_path -%}
    {%- set projectNumber = repliesMap[projectNumberPath]|reply_str_value -%}
    {%- set projectStartPath = [projectsPath, projectsItem, uuids.projectStartQUuid]|reply_path -%}
    {%- set projectStart = repliesMap[projectStartPath]|reply_str_value -%}
    {%- set projectEndPath = [projectsPath, projectsItem, uuids.projectEndQUuid]|reply_path -%}
    {%- set projectEnd = repliesMap[projectEndPath]|reply_str_value -%}
    {%- set fundersPath = [projectsPath, projectsItem, uuids.fundersQUuid]|reply_path -%}
    {%- set fundersItems = repliesMap[fundersPath]|reply_items -%}
      {% if projectNumber or projectStart or projectEnd or fundersItems or output_profile|default('review') != 'submission' %}<table class="project-details"><tbody>
        {% if projectNumber or output_profile|default('review') != 'submission' %}<tr>{# __tr_block_0002:start #}<th scope="row">專案編號</th>{# __tr_block_0002:end #}{# __tr_block_0003:start #}<td>{# __tr_inline_if_original:e3sgcHJvamVjdE51bWJlciBpZiBwcm9qZWN0TnVtYmVyIGVsc2UgIk4vQSIgfX0= #}{% if projectNumber %}{{ projectNumber }}{% else %}尚未提供{% endif %}{# __tr_inline_if_original:end #}</td>{# __tr_block_0003:end #}</tr>{% endif %}
